{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.FileInputSchema",
  "description": "Schema for a file input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected file.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.AudioInputSchema",
  "description": "Schema for an audio input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected audio.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "type": [
        "string",
        "null"
      ]
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    }
  },
  "required": [
    "items"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "oneOf": [
    {
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "const": "text"
        }
      },
      "required": [
        "type",
        "text"
      ]
    },
    {
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "const": "image_url"
        }
      },
      "required": [
        "type",
        "image_url"
      ]
    },
    {
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "const": "input_audio"
        }
      },
      "required": [
        "type",
        "input_audio"
      ]
    },
    {
      "description": "Video input.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "input_video"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "video_url"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "const": "file"
        }
      },
      "required": [
        "type",
        "file"
      ]
    }
  ]
}
